# db/queries.py (snippets)
NAME_RE = re.compile(r"^[A-Za-z0-9_]+$")

def _validate_identifier(name: str) -> None:
    if not NAME_RE.fullmatch(name):
        raise ValidationError("Invalid identifier")

def get_user_by_email(conn: Connection, email: str) -> Optional[Dict[str, Any]]:
    """Return user row by email. Uses parameterized query."""
    sql_q = "SELECT id, email, name FROM users WHERE email = %s"
    with conn.cursor() as cur:
        cur.execute(sql_q, (email,))
        row = cur.fetchone()
    return dict(row) if row else None

from psycopg2 import sql

def select_from_table(conn: Connection, table: str, column: str, value: str):
    _validate_identifier(table)
    _validate_identifier(column)
    q = sql.SQL("SELECT {cols} FROM {table} WHERE {col} = %s").format(
        cols=sql.SQL(', ').join([sql.Identifier('id'), sql.Identifier('name')]),
        table=sql.Identifier(table),
        col=sql.Identifier(column),
    )
    with conn.cursor() as cur:
        cur.execute(q, (value,))
        return cur.fetchall()

def update_user_email(conn: Connection, user_id: int, email: str) -> None:
    """Transactionally update user email; DB rollback will occur automatically on exception."""
    with conn:  # context manager commits or rolls back
        with conn.cursor() as cur:
            cur.execute("UPDATE users SET email = %s WHERE id = %s", (email, user_id))

