# middleware/authz.py (snippets)
from enum import Enum
class Role(Enum):
    USER = 'user'
    ADMIN = 'admin'

def authorize(allowed_roles: Optional[Set[Role]] = None, require_owner: bool = False):
    def decorator(handler):
        @wraps(handler)
        def wrapper(req, *args, **kwargs):
            user = getattr(req, 'user', None)
            if not user:
                return http_error(401)
            if require_owner:
                resource = load_resource(kwargs.get('id'))
                if resource is None:
                    return http_error(404)
                if resource.owner_id != user.id and Role.ADMIN.value not in user.roles:
                    logger.warning('authz: forbidden user_id=%s resource_id=%s', redact(user.id), redact(resource.id))
                    return http_error(403)
            if allowed_roles and not any(r.value in user.roles for r in allowed_roles):
                return http_error(403)
            return handler(req, *args, **kwargs)
        return wrapper
    return decorator

