# middleware/csrf.py (snippets)
SECRET_KEY = settings.CSRF_SECRET
TOKEN_TTL = 60 * 60  # 1 hour

def generate_csrf_token(session_id: str) -> str:
    ts = str(int(time.time()))
    mac = hmac.new(SECRET_KEY, f"{session_id}|{ts}".encode('utf-8'), hashlib.sha256).hexdigest()
    return f"{ts}:{mac}"

def validate_csrf_token(session_id: str, token: str) -> bool:
    try:
        ts_s, mac = token.split(':', 1)
        ts = int(ts_s)
    except Exception:
        return False
    if abs(int(time.time()) - ts) > TOKEN_TTL:
        return False
    expected = hmac.new(SECRET_KEY, f"{session_id}|{ts_s}".encode('utf-8'), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, mac)

# Setting cookie when issuing token (example)
