from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import List, Dict, Optional, Union, TypedDict

CURRENCY_QUANT = Decimal('0.01')

class RevenueError(ValueError):
    pass


class OrderItem(TypedDict):
    price: Union[str, int, float, Decimal]
    quantity: Union[int, str, Decimal]


class Discount(TypedDict):
    type: str
    value: Union[str, int, float, Decimal]


def _to_decimal(value) -> Decimal:
    """Convert a value to Decimal. Fast-path if already Decimal."""
    if isinstance(value, Decimal):
        return value
    try:
        return Decimal(str(value))
    except (InvalidOperation, TypeError):
        raise RevenueError(f"Invalid numeric value: {value}")


def calculate_revenue(order_items: List[OrderItem], discounts: Optional[List[Discount]] = None) -> Decimal:
    """Calculate total revenue for order_items.

    order_items: list of OrderItem {price: number/string/Decimal (>=0), quantity: int (>=1) or digit-string}
    discounts: optional list of Discount {type: 'percent' | 'fixed', value: number}, or None

    Percent discount semantics: value may be specified as percentage points (e.g. 10 => 10%)
    or as a fractional representation between 0 and 1 (e.g. 0.1 => 10%). Both are accepted.

    Returns: Decimal quantized to 2 decimal places.
    """
    if not isinstance(order_items, list):
        raise RevenueError("order_items must be a list")

    total = Decimal('0')

    for idx, item in enumerate(order_items):
        if not isinstance(item, dict):
            raise RevenueError(f"order_items[{idx}] must be a dict")
        if 'price' not in item or 'quantity' not in item:
            raise RevenueError(f"order_items[{idx}] missing price or quantity")

        price = _to_decimal(item['price'])

        # Quantity validation: reject bools and fractional values.
        q = item['quantity']
        if isinstance(q, bool):
            raise RevenueError(f"order_items[{idx}] has invalid price/quantity")
        if isinstance(q, Decimal):
            if q != q.to_integral_value():
                raise RevenueError(f"order_items[{idx}] quantity must be an integer")
            quantity = int(q)
        elif isinstance(q, int):
            quantity = q
        elif isinstance(q, str) and q.isdigit():
            quantity = int(q)
        else:
            # This rejects floats with fractional parts and other invalid forms
            raise RevenueError(f"order_items[{idx}] quantity must be an integer")

        if price < 0 or quantity <= 0:
            raise RevenueError(f"order_items[{idx}] has invalid price/quantity")

        line = price * quantity
        total += line

    # apply discounts (validated). Distinguish between None and empty list.
    if discounts is not None:
        if not isinstance(discounts, list):
            raise RevenueError("discounts must be a list")
        for didx, d in enumerate(discounts):
            if not isinstance(d, dict) or 'type' not in d or 'value' not in d:
                raise RevenueError(f"discounts[{didx}] invalid")
            dval = _to_decimal(d['value'])
            if dval < 0:
                raise RevenueError(f"discounts[{didx}] value must be >= 0")
            if d['type'] == 'percent':
                # Accept either percentage points (0-100) or fractional (0.0-1.0)
                if dval <= Decimal('1'):
                    percent = dval * Decimal('100')
                else:
                    percent = dval
                if percent > Decimal('100'):
                    raise RevenueError(f"discounts[{didx}] percent > 100")
                total -= (total * percent / Decimal('100'))
            elif d['type'] == 'fixed':
                total -= dval
            else:
                raise RevenueError(f"discounts[{didx}] unknown type")

    # ensure non-negative and quantize to 2 decimal places
    if total < 0:
        total = Decimal('0')
    return total.quantize(CURRENCY_QUANT, rounding=ROUND_HALF_UP)

